-- ══════════════════════════════════════════════════════════════════════════════
-- 0269_academy_niveau1_modules2_3.sql
-- Enrichissement substantiel des 7 leçons des Modules 2 et 3 (Niveau 1 : leçons 5 à 11)
-- Généré par frontend/scripts/academy-niveau1-modules2-3.mjs le 2026-11-24
-- Données réelles figées : frontend/lib/academy/contenus/sources/niveau1-modules2-3-2026-11-24.json
-- Idempotent : vérifie la position et le préfixe de chaque titre avant mise à jour.
-- ══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_content jsonb;
BEGIN
  SELECT content INTO v_content
  FROM public.academy_courses
  WHERE slug = 'academy-niveau-1-initiation'
  FOR UPDATE;

  IF v_content IS NULL THEN
    RAISE EXCEPTION 'Cours academy-niveau-1-initiation introuvable';
  END IF;

  -- Position 4 (lecon5-dividendes.json)
  IF NOT ((v_content->'lessons'->4->>'titre') LIKE 'Leçon 5 — %') THEN
    RAISE EXCEPTION 'Migration 0269 interrompue : leçon en position 4 inattendue (%)', v_content->'lessons'->4->>'titre';
  END IF;
  v_content := jsonb_set(
    v_content,
    '{lessons,4}',
    (v_content->'lessons'->4) || $L4_M23_0${"titre":"Leçon 5 — Les dividendes : se constituer un revenu régulier","image":{"url":"https://images.pexels.com/photos/6928996/pexels-photo-6928996.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","alt":"Calendrier, loupe et pièces de monnaie posés sur un bureau","credit":"Photo : Leeloo The First / Pexels"},"categorie":"income","duree_min":12,"sous_titre":"Comprendre le mécanisme, calculer son rendement et mesurer l’effet du réinvestissement.","resume":"Un dividende est la part du bénéfice qu’une société cotée verse à ses actionnaires.\nBien compris, il peut devenir une source de revenus régulière, à condition de savoir le calculer, le lire et en mesurer les limites.","avertissement":"Ceci n’est pas un conseil en investissement. Les dividendes ne sont pas garantis. Investir en actions comporte un risque de perte en capital.","quiz":[{"question":"Vous détenez 200 actions et la société verse 1 500 FCFA par action. Quel est votre revenu brut ?","options":["30 000 FCFA","150 000 FCFA","300 000 FCFA","3 000 000 FCFA"],"correct":2,"explication":"Revenu brut = nombre d’actions × dividende par action : 200 × 1 500 = 300 000 FCFA."},{"question":"Une action cote 20 000 FCFA et verse un dividende annuel de 1 200 FCFA. Quel est son rendement ?","options":["1,2 %","6 %","12 %","16,7 %"],"correct":1,"explication":"Rendement = dividende ÷ cours × 100 : 1 200 ÷ 20 000 × 100 = 6 %."},{"question":"Quelle stratégie amplifie vos dividendes par effet boule de neige ?","options":["Vendre ses actions dès réception du dividende","Placer les dividendes sur un compte bancaire","Réinvestir les dividendes en actions","Attendre 5 ans avant de toucher à son portefeuille"],"correct":2,"explication":"Les actions achetées avec le dividende rapportent à leur tour un dividende l’année suivante, qui permet d’en acheter davantage."},{"question":"Pour percevoir le prochain dividende, jusqu’à quand faut-il détenir l’action ?","options":["Le jour du paiement","La veille de la date de détachement","Le jour de l’assemblée générale","Un an avant le paiement"],"correct":1,"explication":"Il faut détenir l’action la veille du détachement. Acheter le jour du détachement ou après ne donne pas droit au dividende en cours."},{"question":"Une action affiche un rendement de 15 %, bien au-dessus des autres. Que peut-on en conclure ?","options":["C’est forcément un excellent placement","Le dividende va augmenter l’an prochain","Il faut vérifier d’où vient ce chiffre","La société est sûrement la plus rentable du marché"],"correct":2,"explication":"Un rendement très élevé est un signal à vérifier, pas une garantie : il peut venir d’un cours qui a chuté, ou d’un dividende que le marché juge intenable."},{"question":"Quel capital faut-il pour viser 600 000 FCFA de dividendes bruts par an, à 8 % de rendement hypothétique ?","options":["48 000 FCFA","4 800 000 FCFA","7 500 000 FCFA","10 000 000 FCFA"],"correct":2,"explication":"Capital = revenu visé ÷ rendement : 600 000 ÷ 8 % = 7 500 000 FCFA. À 6 %, il en faudrait 10 000 000."},{"question":"En Côte d’Ivoire depuis 2025, quel est le taux d’IRVM retenu sur les dividendes d’actions cotées pour un particulier ?","options":["5 %","10 %","12 %","25 %"],"correct":2,"explication":"Depuis la loi de finances 2025, l’IRVM en Côte d’Ivoire est de 12 % pour les personnes physiques (10 % pour les personnes morales)."},{"question":"Un dividende brut de 1 940 FCFA soumis à 12 % d’IRVM donne quel montant net perçu par action ?","options":["1 707,20 FCFA","1 746,00 FCFA","1 820,00 FCFA","1 928,00 FCFA"],"correct":0,"explication":"1 940 × (1 − 0,12) = 1 707,20 FCFA nets (cas réel STBC sur l’exercice 2025)."},{"question":"Que montre la comparaison entre SNTS (140 → 174 FCFA) et SPHC (365 → 65 → 430 FCFA) sur 5 ans ?","options":["Tous les dividendes progressent chaque année","Un dividende cyclique peut baisser fortement si l’activité recule","Les actions agricoles versent des dividendes fixes","Le dividende ne dépend pas du bénéfice"],"correct":1,"explication":"Le dividende suit la capacité bénéficiaire : il est stable ou croissant sur les valeurs défensives, et volatil sur les valeurs cycliques."},{"question":"Que se passe-t-il techniquement sur le cours le matin du détachement d’un dividende ?","options":["Le cours double automatiquement","Le cours est ajusté à la baisse du montant du dividende","La cotation est suspendue pendant un mois","Le dividende est annulé pour les anciens actionnaires"],"correct":1,"explication":"Le jour du détachement, le cours de référence est ajusté du dividende détaché : toucher le dividende la veille n’est donc pas un gain gratuit."}],"sections":[{"type":"definition","titre":"Comprendre le dividende","contenu":"Quand une société réalise un bénéfice, son assemblée générale décide d’en verser une partie aux actionnaires : c’est le dividende.\nLe reste est conservé en réserves pour financer l’activité ou rembourser la dette. Une société bénéficiaire peut aussi choisir de ne rien distribuer.\nÀ la BRVM, la quasi-totalité des sociétés versent un dividende annuel unique, voté entre avril et juillet après la clôture des comptes.\nEn 2026, le calendrier officiel de la BRVM recense 34 valeurs ayant daté et payé un dividende au titre de l’exercice 2025.","flux":[{"titre":"Entreprise","detail":"Réalise un bénéfice sur l’exercice.","icone":"entreprise"},{"titre":"Bénéfice distribuable","detail":"La part qui peut être versée.","icone":"benefices"},{"titre":"Décision de distribution","detail":"Votée en assemblée générale.","icone":"decision"},{"titre":"Actionnaires","detail":"Reçoivent le dividende, par action détenue.","icone":"actionnaires"}],"formules":[{"nom":"Revenu brut","expression":"Nombre d’actions × Dividende par action","exemple":"300 × 1 000 FCFA = 300 000 FCFA"},{"nom":"Rendement du dividende","expression":"Dividende annuel par action ÷ Cours de l’action × 100","exemple":"1 000 ÷ 10 000 × 100 = 10 %"}]},{"type":"cas","titre":"Un exemple chiffré","contenu":"Un investisseur détient 300 actions. La société verse 1 000 FCFA par action, et l’action cote 10 000 FCFA.\nIl perçoit 300 000 FCFA bruts dans l’année, soit un rendement brut de 10 % au cours de 10 000 FCFA. Ces chiffres sont pédagogiques.\nSur le marché réel au 24 novembre 2026, les meilleurs rendements nets datés atteignent 8,37 % sur STBC (1707,20 FCFA nets pour 20 395 FCFA) et 7,78 % sur ABJC (201,52 FCFA nets pour 2 590 FCFA).\nLe tableau ci-dessous applique le calcul réel à quatre valeurs liquides pour 300 actions, en montants nets d’impôt tels que versés.","donnees_reelles":{"vue":"rendement","codes":["SNTS","ORAC","SGBC","SDCC"],"actions":300},"stats":[{"label":"Actions détenues","valeur":"300"},{"label":"Dividende par action","valeur":"1 000 FCFA"},{"label":"Revenu brut annuel","valeur":"300 000 FCFA"},{"label":"Rendement brut","valeur":"10 %","detail":"au cours de 10 000 FCFA"}],"graphiques":[{"type":"bar","titre":"Meilleurs rendements nets de dividende à la BRVM (ex. 2025, en %)","reel":true,"note":"Sources : Calendrier officiel des dividendes BRVM (ex. 2025) et clôtures du 24/11/2026. Montants nets d’IRVM.","labels":["STBC","NEIC","ABJC","BOAB","SGBC","PALC","SPHC"],"valeurs":[8.37,7.8,7.78,7.13,6.11,6.05,5.78]}]},{"type":"cas","titre":"Réinvestir ses dividendes","contenu":"Plutôt que de dépenser le dividende, on peut s’en servir pour acheter de nouvelles actions. L’année suivante, ces actions rapportent à leur tour un dividende.\nAnnée 1 : 300 actions × 1 000 FCFA = 300 000 FCFA, réinvestis à 10 000 FCFA l’action, soit 30 actions de plus. Année 2 : 330 actions × 1 050 FCFA = 346 500 FCFA.\nLe graphique compare ce choix avec des dividendes conservés en espèces, sous les hypothèses écrites dessous.","simulation":{"type":"reinvestissement","actions":300,"dpa":1000,"cours":10000,"croissance_pct":5,"annees":6}},{"type":"importance","titre":"Analyser une action à dividendes","contenu":"Un dividende élevé n’est pas forcément un bon dividende. Cinq questions permettent d’en juger avant d’acheter.\nRegardez d’abord la trajectoire sur cinq ans : SGBC a porté son dividende net de 1 005 FCFA (2021) à 2 293,28 FCFA (2025) et SNTS de 140 à 174 FCFA.\nÀ l’inverse, SPHC est passée de 365,40 FCFA (2021) à 65 FCFA (2023) avant de remonter à 430,32 FCFA (2025) : un dividende cyclique suit la matière première.\nLe tableau ci-dessous confronte quatre historiques réels sur cinq exercices pour distinguer régularité et cyclicité.","donnees_reelles":{"vue":"historique","codes":["SNTS","ORAC","SGBC","SPHC"]},"points":[{"titre":"Régularité des distributions","detail":"Une société qui verse chaque année, sans interruption, inspire plus de confiance qu’une distribution exceptionnelle.","verifier":"les dividendes versés sur au moins cinq exercices."},{"titre":"Capacité bénéficiaire","detail":"Le dividende est payé par le bénéfice. Un bénéfice qui recule finit par peser sur la distribution.","verifier":"l’évolution du résultat net sur plusieurs années."},{"titre":"Taux de distribution","detail":"C’est la part du bénéfice versée aux actionnaires. Proche ou au-delà de 100 %, la société distribue plus qu’elle ne gagne.","verifier":"dividendes totaux ÷ résultat net."},{"titre":"Rendement au cours de référence","detail":"Le rendement dépend du prix payé : le même dividende rapporte moins si l’action a été achetée plus cher.","verifier":"le rendement au cours du jour, et non au cours d’il y a un an."},{"titre":"Valorisation et risques","detail":"Un rendement très élevé peut traduire une action dont le cours a chuté, parce que le marché doute de la suite.","verifier":"le PER, l’endettement et l’actualité de la société."}],"graphiques":[{"type":"line","titre":"Dividende net versé sur 5 ans : régularité (SNTS) vs cyclicité (SPHC)","reel":true,"note":"Sources : BRVM (calendrier officiel 2025) et historiques 2021–2024 (SNTS ajusté du fractionnement par 10).","labels":["2021","2022","2023","2024","2025"],"valeurs":[],"series":[{"nom":"SNTS (FCFA net)","valeurs":[140,150,158,166,174],"type":"line","axe":"gauche"},{"nom":"SPHC (FCFA net)","valeurs":[365.4,294,65,324,430.32],"type":"line","axe":"gauche"}]}]},{"type":"importance","titre":"Les dates qui comptent","contenu":"Trois dates encadrent chaque dividende. Pour l’investisseur, la plus décisive est la date de détachement (ex-date).\nIl faut détenir l’action la veille du détachement pour percevoir le dividende. Acheter le jour même ou après ne donne aucun droit au coupon en cours.\nEn pratique, le paiement intervient 1 à 3 jours ouvrés après : STBC a détaché le 2026-08-12 et payé le 2026-08-13 ; ABJC a détaché le 2026-09-29 et payé le 2026-09-30.","etapes_style":"frise","etapes":[{"titre":"Décision de distribution","detail":"L’assemblée générale approuve le montant du dividende."},{"titre":"Date de détachement","detail":"Seuls les détenteurs de la veille y ont droit ; le cours est ajusté du dividende.","cle":true},{"titre":"Date de paiement","detail":"Le dividende est versé sur le compte espèces associé à votre compte-titres, par votre SGI."}]},{"type":"piege","titre":"Les erreurs à éviter","contenu":"Cinq erreurs reviennent souvent chez les investisseurs qui découvrent les dividendes, notamment oublier l’impôt retenu à la source (IRVM).\nEn Côte d’Ivoire, l’IRVM sur dividendes cotés est de 12 % pour les personnes physiques depuis 2025 (10 % pour les personnes morales).\nExemple réel : sur STBC, le dividende brut voté est de 1 940 FCFA, mais l’actionnaire particulier perçoit 1707,20 FCFA nets après 12 % d’IRVM.","points":[{"titre":"Choisir sur le seul rendement","detail":"Un rendement très élevé peut annoncer une baisse du dividende ou du cours."},{"titre":"Acheter juste avant le détachement pour « toucher » le dividende","detail":"Au détachement, le cours est ajusté du dividende : le gain n’est pas gratuit."},{"titre":"Oublier les impôts et les frais","detail":"Le dividende est versé après retenue à la source, et chaque ordre coûte des frais de courtage."},{"titre":"Supposer que le dividende se répétera","detail":"Il est voté chaque année : il peut baisser, ou disparaître."},{"titre":"Tout miser sur une seule valeur","detail":"Une société, un secteur ou un pays peut traverser une mauvaise année. Répartir réduit ce risque."}]},{"type":"cas","titre":"Calculer un objectif de revenus","contenu":"Voici les ordres de grandeur pour viser un revenu annuel de dividendes, selon trois taux de rendement hypothétiques.\nCes chiffres reposent sur des hypothèses constantes (aucune baisse du dividende ni frais de courtage inclus) : ils donnent un cap, pas une promesse.\nPour réduire l’effort d’épargne, le réinvestissement automatique des premiers coupons permet de bâtir progressivement le nombre d’actions génératrices de revenus.","formules":[{"nom":"Capital nécessaire","expression":"Revenu annuel visé ÷ Rendement","exemple":"600 000 ÷ 6 % = 10 000 000 FCFA"}],"simulation":{"type":"objectif","revenu_cible":600000,"rendements_pct":[6,8]}},{"type":"retenir","titre":"L’essentiel","contenu":"Le dividende rémunère la patience, à condition de ne jamais sacrifier la qualité de l’entreprise pour un taux facial élevé.\nVérifiez toujours : la base nette d’impôt, la régularité sur 5 ans, le taux de distribution du bénéfice et la liquidité du titre avant d’entrer.","points":[{"titre":"Le dividende est une part du bénéfice","detail":"Voté chaque année, il n’est jamais garanti."},{"titre":"Revenu = actions × dividende par action","detail":"300 actions × 1 000 FCFA = 300 000 FCFA bruts."},{"titre":"Rendement = dividende ÷ cours × 100","detail":"Il dépend du prix payé pour l’action."},{"titre":"Réinvestir accroît les revenus futurs","detail":"Les actions achetées produisent à leur tour un dividende."},{"titre":"Le détachement décide du droit au dividende","detail":"Il faut détenir l’action la veille de la date de détachement."}]}],"module":"Module 2 — Dividendes et investissement pratique","nouveaute":{"type":"mis_a_jour","depuis":"2026-11-24"},"charts":[],"qcm":{"question":"Vous détenez 200 actions et la société verse 1 500 FCFA par action. Quel est votre revenu brut ?","options":["30 000 FCFA","150 000 FCFA","300 000 FCFA","3 000 000 FCFA"],"correct":2,"explication":"Revenu brut = nombre d’actions × dividende par action : 200 × 1 500 = 300 000 FCFA."}}$L4_M23_0$::jsonb
  );

  -- Position 5 (lecon6-compte-ordre.json)
  IF NOT ((v_content->'lessons'->5->>'titre') LIKE 'Leçon 6 — %') THEN
    RAISE EXCEPTION 'Migration 0269 interrompue : leçon en position 5 inattendue (%)', v_content->'lessons'->5->>'titre';
  END IF;
  v_content := jsonb_set(
    v_content,
    '{lessons,5}',
    (v_content->'lessons'->5) || $L5_M23_1${"titre":"Leçon 6 — Ouvrir un compte et passer son premier ordre","image":{"url":"https://images.pexels.com/photos/9870227/pexels-photo-9870227.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","alt":"Mains signant un formulaire sur une table","credit":"Photo : Ron Lach / Pexels"},"categorie":"general","duree_min":10,"sous_titre":"Quatre étapes, les bons documents, et le type d’ordre qui protège votre prix.","resume":"Pour acheter des actions à la BRVM, il faut passer par une Société de Gestion et d’Intermédiation (SGI) agréée.\nCette leçon détaille l’ouverture du compte, le dépôt et le premier ordre, avec les réflexes qui évitent les mauvaises surprises.","avertissement":"Ceci n’est pas un conseil en investissement. Les performances passées ne préjugent pas des performances futures. Investir en actions comporte un risque de perte en capital.","sections":[{"type":"definition","titre":"Le parcours en quatre étapes","contenu":"Un particulier ne peut pas acheter d’actions directement sur la BRVM : il doit ouvrir un compte-titres auprès d’une SGI (Société de Gestion et d’Intermédiation) agréée par l’AMF-UMOA (ex-CREPMF).\nFin 2026, l’annuaire officiel recense 40 SGI réparties dans 7 pays de l’UEMOA : 20 en Côte d’Ivoire, 6 au Sénégal, 5 au Bénin, 4 au Burkina Faso, 3 au Mali, 1 au Niger et 1 au Togo.\nChaque compte-titres est adossé à un compte espèces dédié qui reçoit vos dépôts, règle vos achats et encaisse automatiquement vos dividendes nets.","flux":[{"titre":"Choisir une SGI","detail":"Agréée par l’autorité de régulation, l’AMF-UMOA.","icone":"entreprise"},{"titre":"Constituer le dossier","detail":"Pièce d’identité, justificatif de domicile, formulaire.","icone":"decision"},{"titre":"Déposer des fonds","detail":"Virement ou dépôt sur le compte espèces.","icone":"paiement"},{"titre":"Passer un ordre","detail":"Choisir la valeur, la quantité et le prix.","icone":"graphique"}],"graphiques":[{"type":"bar","titre":"Répartition des 40 SGI agréées par pays de l’UEMOA","reel":true,"note":"Sources : Annuaire officiel des SGI BRVM / AMF-UMOA (2026).","labels":["Côte d’Ivoire","Sénégal","Bénin","Burkina Faso","Mali","Niger","Togo"],"valeurs":[20,6,5,4,3,1,1]}]},{"type":"importance","titre":"Choisir sa SGI","contenu":"Les documents demandés sont standards : pièce d’identité en cours de validité, justificatif de domicile, photo, RIB ou numéro Mobile Money et fiche de connaissance client (KYC).\nSur 37 grilles tarifaires publiées, le dépôt minimum varie fortement d’une SGI à l’autre : de 0 FCFA ou 50 000 FCFA jusqu’à 2 000 000 FCFA selon le positionnement.\nL’ouverture prend généralement quelques jours ouvrés, parfois entièrement en ligne selon la SGI choisie.","points":[{"titre":"L’agrément","detail":"Seules les SGI agréées peuvent exécuter vos ordres à la BRVM.","verifier":"la liste des SGI agréées publiée par l’AMF-UMOA (ex-CREPMF)."},{"titre":"Les frais","detail":"Frais de courtage à chaque ordre, frais de tenue de compte, commissions : ils pèsent lourd sur les petits montants.","verifier":"la grille tarifaire complète, avant d’ouvrir le compte."},{"titre":"La plateforme et le service","detail":"Ordres en ligne, suivi du portefeuille, réactivité en cas de question.","verifier":"les moyens de passer un ordre : en ligne, par téléphone, en agence."},{"titre":"Le dépôt minimum","detail":"Il varie d’une SGI à l’autre.","verifier":"le montant exigé à l’ouverture."}]},{"type":"definition","titre":"Deux types d’ordres","contenu":"Avant de choisir une SGI, comparez quatre postes de frais : la commission de courtage par ordre, les droits de garde annuels, la tenue de compte et les frais de retrait ou de virement.\nSur les grilles homologuées en base, le courtage se situe typiquement entre 0,65 % et 1 % par transaction (parfois avec un minimum de perception de 1 000 FCFA).\nLes droits de garde annuels vont souvent de 0,25 % à 0,50 % du portefeuille, et la tenue de compte est nulle chez de nombreuses SGI (ou jusqu’à 12 500 FCFA/an ailleurs).","points":[{"titre":"L’ordre à cours limité","detail":"Vous fixez un prix maximum. Pour un achat, l’ordre ne s’exécute qu’à ce prix ou en dessous ; sinon il reste en attente pendant sa durée de validité (une seule séance par défaut).","verifier":"le dernier cours et les prix proposés avant de fixer votre limite."},{"titre":"L’ordre au mieux","detail":"Vous acceptez le meilleur prix disponible au moment de l’exécution. Plus rapide, mais sans contrôle du prix.","verifier":"les volumes échangés : sur une valeur peu liquide, le prix obtenu peut s’éloigner du dernier cours."}]},{"type":"cas","titre":"Le coût réel d’un premier achat","contenu":"Passer un ordre revient à donner trois instructions précises : le sens (achat ou vente), la quantité de titres et le type de prix.\nAvec un ordre à cours limité, vous fixez le prix maximum d’achat (ou minimum de vente). Avec un ordre au mieux, vous acceptez le prix disponible dans le carnet.\nLa leçon 7 y ajoute la durée de validité (ordre « jour » ou « à révocation ») et les conditions d’exécution face au carnet d’ordres.","formules":[{"nom":"Coût total d’un achat","expression":"Quantité × Cours + Frais","exemple":"20 × 10 000 + 1 % = 202 000 FCFA"}],"simulation":{"type":"frais_ordre","consigne":"Reprenez l’exemple, puis réduisez la quantité : avec un minimum de frais, le coût d’un très petit ordre grimpe vite.","cours":10000,"quantite":20,"taux_frais_pct":1,"minimum_fcfa":0},"illustration":{"gabarit":"decomposition","titre":"Le coût d’un achat : les titres, plus les frais (exemple pédagogique)","operation":"somme","unite":"FCFA","resultat":{"label":"Coût total de l’ordre","valeur":202000},"facteurs":[{"label":"20 actions à 10 000 FCFA","valeur":200000},{"label":"Frais (1 %)","valeur":2000}],"note":"Avec 1 % de frais, 20 actions à 10 000 FCFA coûtent 202 000 FCFA. Sur un très petit ordre, un minimum de frais peut peser bien plus que 1 % : le simulateur ci-dessous le montre."}},{"type":"cas","reel":true,"titre":"Sur la BRVM : le prix de 20 actions","contenu":"Sur le Bulletin Officiel de la Cote du 23 novembre 2026, le carnet d’ORAC affichait 51 titres à l’achat à 19 000 FCFA face à 64 titres à la vente à 19 005 FCFA : un écart très serré de 5 FCFA.\nSur NSBC le même jour, 50 titres étaient demandés à 14 950 FCFA face à 344 titres offerts à 15 000 FCFA.\nSur SNTS, 27 691 titres attendaient à l’achat à 3 900 FCFA contre 20 titres offerts à 3 990 FCFA : un ordre au mieux trop gros aurait payé plus cher.","donnees_reelles":{"vue":"cours","codes":["SNTS","ORAC","SIBC","BOAB"],"actions":20}},{"type":"piege","titre":"Les erreurs à éviter","contenu":"Deux réflexes protègent vos premiers ordres : vérifiez toujours le montant total frais inclus, et privilégiez l’ordre à cours limité sur les titres peu liquides.\nCommencez par un petit ordre sur une valeur liquide pour tester le parcours complet de votre SGI (dépôt, exécution, avis d’opéré).","points":[{"titre":"Passer un ordre au mieux sur une valeur peu échangée","detail":"Le prix payé peut être nettement supérieur au dernier cours affiché."},{"titre":"Confier ses fonds à un intermédiaire non agréé","detail":"Plateformes et « courtiers » non agréés sont une source fréquente d’arnaques."},{"titre":"Oublier les frais sur les petits ordres","detail":"Mieux vaut regrouper ses achats que multiplier les très petits ordres."},{"titre":"Signer sans lire les conditions","detail":"Frais, délais et modalités de retrait figurent dans la convention de compte."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Cinq idées à garder en tête.","points":[{"titre":"On investit à la BRVM par une SGI agréée","detail":"L’agrément se vérifie auprès de l’AMF-UMOA."},{"titre":"Quatre étapes","detail":"Choisir la SGI, constituer le dossier, déposer, passer l’ordre."},{"titre":"L’ordre à cours limité protège votre prix","detail":"C’est le réflexe recommandé pour débuter."},{"titre":"Coût total = quantité × cours + frais","detail":"Les frais comptent, surtout sur les petits montants."},{"titre":"Méfiance envers les plateformes non agréées","detail":"Aucun agrément, aucun dépôt."}]}],"quiz":[{"question":"Quel type d’ordre permet de contrôler son prix d’achat ?","options":["Ordre au mieux, pour être servi au plus vite","Ordre à cours limité, avec un prix maximum","Ordre stop, déclenché à un seuil de prix","Aucun : tous les ordres se valent"],"correct":1,"explication":"L’ordre à cours limité fixe un prix maximum d’achat : vous maîtrisez votre coût d’entrée, en particulier sur les valeurs peu liquides."},{"question":"Par qui faut-il passer pour acheter des actions à la BRVM ?","options":["Sa banque, directement au guichet","Une SGI agréée","N’importe quelle plateforme en ligne","La BCEAO"],"correct":1,"explication":"Seules les Sociétés de Gestion et d’Intermédiation agréées peuvent transmettre des ordres au marché de la BRVM."},{"question":"Quelle autorité agrée les SGI de l’UMOA ?","options":["La BCEAO","L’AMF-UMOA (ex-CREPMF)","La BRVM elle-même","Le ministère des Finances de chaque pays"],"correct":1,"explication":"L’Autorité des Marchés Financiers de l’UMOA, qui a succédé au CREPMF, agrée et contrôle les SGI."},{"question":"Vous achetez 20 actions à 10 000 FCFA avec 1 % de frais. Quel est le coût total ?","options":["200 000 FCFA","202 000 FCFA","220 000 FCFA","200 100 FCFA"],"correct":1,"explication":"20 × 10 000 = 200 000 FCFA, plus 1 % de frais (2 000 FCFA) : 202 000 FCFA."},{"question":"Un ordre d’achat à cours limité à 10 000 FCFA s’exécute :","options":["À 10 000 FCFA ou moins","Seulement au-dessus de 10 000 FCFA","Toujours immédiatement, quel que soit le prix","Au cours d’ouverture, quel qu’il soit"],"correct":0,"explication":"Pour un achat, la limite est un prix maximum : l’ordre s’exécute à 10 000 FCFA ou en dessous ; sinon il reste en attente pendant sa durée de validité."},{"question":"Dans les grilles tarifaires des SGI de la BRVM, dans quelle fourchette se situe généralement la commission de courtage ?","options":["0,01 % à 0,05 %","0,65 % à 1 % par ordre","5 % à 10 % par ordre","Toujours gratuite"],"correct":1,"explication":"Sur les grilles SGI homologuées, le courtage se situe typiquement entre 0,65 % et 1 % par transaction (avec parfois un minimum de perception)."},{"question":"Que sont les « droits de garde » prélevés par une SGI ?","options":["Une amende en cas de perte","Des frais annuels pour la conservation de vos titres en portefeuille","La taxe sur les dividendes","Le prix d’un ordre annulé"],"correct":1,"explication":"Les droits de garde rémunèrent la conservation et le suivi administratif de vos titres (souvent 0,25 % à 0,50 % par an)."},{"question":"Pourquoi l’ordre « à cours limité » est-il recommandé face à un carnet peu profond ?","options":["Il garantit une hausse du titre","Il supprime les frais de courtage","Il vous protège contre une exécution à un prix nettement plus élevé que prévu","Il évite de payer l’IRVM"],"correct":2,"explication":"L’ordre à cours limité fixe un plafond de prix : vous ne payez jamais plus cher que votre limite, même si les vendeurs sont rares."},{"question":"À quoi sert le compte espèces associé à votre compte-titres chez la SGI ?","options":["À détenir uniquement des devises étrangères","À déposer vos fonds, régler vos ordres et encaisser vos dividendes","À emprunter automatiquement à la BCEAO","À bloquer vos actions pendant 10 ans"],"correct":1,"explication":"Toute opération de trésorerie (dépôt, achat, vente, coupon, dividende) transite par votre compte espèces SGI."}],"qcm":{"question":"Quel type d’ordre permet de contrôler son prix d’achat ?","options":["Ordre au mieux, pour être servi au plus vite","Ordre à cours limité, avec un prix maximum","Ordre stop, déclenché à un seuil de prix","Aucun : tous les ordres se valent"],"correct":1,"explication":"L’ordre à cours limité fixe un prix maximum d’achat : vous maîtrisez votre coût d’entrée, en particulier sur les valeurs peu liquides."},"liens":[{"label":"Comparateur de SGI","href":"/comparateur-sgi"},{"label":"Classement de liquidité","href":"/liquidite"}],"module":"Module 3 — Stratégies et compte","nouveaute":{"type":"mis_a_jour","depuis":"2026-11-24"},"charts":[]}$L5_M23_1$::jsonb
  );

  -- Position 6 (lecon7-risques.json)
  IF NOT ((v_content->'lessons'->6->>'titre') LIKE 'Leçon 7 — %') THEN
    RAISE EXCEPTION 'Migration 0269 interrompue : leçon en position 6 inattendue (%)', v_content->'lessons'->6->>'titre';
  END IF;
  v_content := jsonb_set(
    v_content,
    '{lessons,6}',
    (v_content->'lessons'->6) || $L6_M23_2${"titre":"Leçon 7 — Les risques : apprendre avant d’investir","image":{"url":"https://images.pexels.com/photos/128867/coins-currency-investment-insurance-128867.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200","alt":"Pile de pièces de monnaie devant une horloge","credit":"Photo : Pixabay / Pexels"},"categorie":"general","duree_min":14,"sous_titre":"Anticiper une perte, protéger son capital, passer un ordre correctement, et décider calmement quand le marché baisse.","resume":"Investir en actions, c’est accepter l’incertitude : un cours peut baisser, un dividende peut diminuer, une action peut être difficile à revendre. Cette leçon apprend à identifier les trois grands risques, à s’en protéger, à choisir le bon ordre de bourse selon les règles de la BRVM, et à réagir avec méthode à une baisse.","avertissement":"Ceci n’est pas un conseil en investissement. Les actions comportent un risque de perte partielle ou totale du capital. Les dividendes ne sont jamais garantis et les performances passées ne préjugent pas des performances futures. Les seuils et allocations cités sont pédagogiques.","sections":[{"type":"definition","titre":"Les trois risques à connaître","contenu":"Investir à la BRVM expose votre capital à des baisses parfois marquées : une action n’est pas un compte sur livret.\nSur les 52 semaines arrêtées au 23 novembre 2026, plusieurs titres ont reculé fortement depuis leur plus-haut : SCRC (−68,6 %, de 3 920 à 1 230 FCFA), SAFC (−53,4 %), UNLC (−50,9 %) et SIVC (−50,2 %).\nCinq risques principaux doivent être compris et mesurés avant d’engager votre épargne.","points":[{"titre":"Le risque de marché","detail":"Une crise, une hausse des taux ou une perte de confiance fait baisser de nombreuses actions en même temps, même les plus solides. La diversification ne l’efface pas.","verifier":"Pourriez-vous supporter une baisse temporaire de 15 à 20 % sans être obligé de vendre ?"},{"titre":"Le risque propre à une entreprise","detail":"Chiffre d’affaires en baisse, rentabilité dégradée, dette excessive, mauvaise décision, perte d’un marché : une seule société peut chuter de 25 % sur une mauvaise nouvelle.","verifier":"Les derniers résultats de chaque société que vous détenez."},{"titre":"Le risque de liquidité","detail":"Une action peut afficher un cours sans qu’il y ait assez d’acheteurs pour vendre vite à ce prix. Il faut alors attendre, fractionner la vente, ou accepter un prix plus bas.","verifier":"Les volumes échangés, la fréquence des échanges et l’écart entre prix acheteur et vendeur."}],"graphiques":[{"type":"bar","titre":"Plus forts reculs réels depuis le plus-haut 52 semaines (%)","reel":true,"note":"Sources : BRVM (cours de clôture et plus-hauts 52 semaines au 23/11/2026).","labels":["SCRC","SAFC","UNLC","SIVC"],"valeurs":[68.6,53.4,50.9,50.2]}]},{"type":"cas","titre":"Le dividende varie : quatre historiques réels","reel":true,"contenu":"Sur un marché étroit comme la BRVM, le risque de liquidité est souvent sous-estimé : vouloir vendre vite peut coûter cher en écart de prix.\nAu 23 novembre 2026, seules 4 valeurs sur 48 sont en classe A de liquidité (SNTS 92/100, SGBC 80, BBGC 79, BOAC 75), 20 en classe B, 18 en classe C et 6 en classe D.\nSur les valeurs les moins liquides de classe D comme PRSC (score 17/100), l’écart entre achat et vente atteint 8,99 %, contre 0,36 % sur BOAC ou 0,75 % sur SNTS.","donnees_reelles":{"vue":"historique","codes":["SNTS","PALC","NTLC","SPHC"]},"points":[{"titre":"L’entreprise réalise-t-elle des bénéfices réguliers ?"},{"titre":"Sa trésorerie finance-t-elle à la fois son activité et sa distribution ?"},{"titre":"Son endettement reste-t-il maîtrisé ?"},{"titre":"Le dividende est-il soutenable dans les années qui viennent ?","detail":"Un rendement très élevé peut venir d’un cours qui a fortement baissé : ce n’est pas automatiquement une affaire."}],"graphiques":[{"type":"bar","titre":"Répartition des 48 actions BRVM par classe de liquidité (A à D)","reel":true,"note":"Sources : Moteur de liquidité WestBourse (données BRVM au 23/11/2026).","labels":["Classe A (très liquide)","Classe B (liquide)","Classe C (modérée)","Classe D (étroite)"],"valeurs":[4,20,18,6]}]},{"type":"importance","titre":"Trois protections, et l’effet de la diversification","contenu":"La leçon 6 a présenté les deux limites de prix (cours limité et au mieux). Face à un carnet réel peu profond, deux autres paramètres évitent les mauvaises surprises.\nLa durée de validité précise si l’ordre expire en fin de séance (« jour ») ou reste actif jusqu’à exécution ou annulation (« à révocation »).\nLa condition « tout ou rien » impose une exécution complète en une fois, utile pour éviter de multiplier les frais sur de micro-exécutions.","points":[{"titre":"Diversifier","detail":"Répartir entre plusieurs sociétés et secteurs. Repères pédagogiques pour un débutant : pas plus de 20 % sur une société, ni plus de 35 % sur un secteur.","verifier":"Deux sociétés différentes peuvent dépendre de la même matière première ou du même marché."},{"titre":"Investir pour plusieurs années","detail":"Un portefeuille de 1 000 000 FCFA qui vaut 850 000 FCFA six mois plus tard a perdu 15 % de valeur, même sans vente. Avec un horizon long, on n’est pas forcé de vendre au mauvais moment."},{"titre":"Se former et suivre ses sociétés","detail":"Chiffre d’affaires, résultat, marge, dette, trésorerie, dividendes, perspectives : un investissement ne s’arrête pas le jour de l’achat."}],"tableau":{"colonnes":["Stratégie","Revenu avant","Revenu après","Baisse"],"lignes":[["Tout sur une seule valeur","80 000","40 000","−50 %"],["Cinq valeurs à parts égales","80 000","72 000","−10 %"]],"note":"Exemple pédagogique : cinq lignes de même montant et de même rendement ; une seule divise son dividende par deux. La diversification n’empêche pas les mauvaises nouvelles, elle évite qu’une seule les fasse toutes subir."},"simulations":[{"type":"allocation","capital":1000000,"secteurs":[{"nom":"Banques","pct":20},{"nom":"Télécoms","pct":20},{"nom":"Agro-industrie","pct":20},{"nom":"Distribution","pct":20},{"nom":"Énergie","pct":20}],"seuil_secteur_pct":35},{"type":"scenario_baisse","capital":1000000,"rendement_pct":8,"secteurs":[{"nom":"Banques","pct":20},{"nom":"Télécoms","pct":20},{"nom":"Agro-industrie","pct":20},{"nom":"Distribution","pct":20},{"nom":"Énergie","pct":20}]}]},{"type":"importance","titre":"Les ordres de bourse selon les règles de la BRVM","contenu":"Un ordre mal rédigé peut faire payer trop cher, ou ne jamais s’exécuter. La leçon 6 a présenté les deux limites de prix : au mieux et à cours limité.\nLe règlement général de la BRVM décrit un ordre par trois caractéristiques : sa limite de prix, sa durée de validité, et ce qu’il accepte en cas de réponse partielle.\nSelon la valeur, les ordres sont confrontés au fixing (un cours d’équilibre unique) ou en continu (chaque ordre rencontre aussitôt le carnet).","tableau":{"colonnes":["Caractéristique","Ce que prévoit le règlement","Ce que cela change pour vous"],"lignes":[["Limite de prix","Au mieux : aucun prix fixé","L’exécution est favorisée, le prix n’est pas maîtrisé"],["Limite de prix","À cours limité : prix maximal à l’achat, minimal à la vente","Le prix est maîtrisé, l’exécution n’est pas garantie"],["Validité","Jour : présenté à la seule séance qui suit sa transmission (choix par défaut)","Non exécuté, il disparaît"],["Validité","Mensuel : jusqu’à la dernière séance du mois","Il reste en attente plusieurs séances"],["Validité","À exécution : sans date, présenté 3 mois au plus ; ou date limite choisie","Il peut s’exécuter longtemps après votre décision"],["Réponse partielle","Sans condition : la quantité est un maximum","Il peut être servi en partie"],["Réponse partielle","Tout ou rien","Servi en totalité, ou pas du tout"]],"note":"Source : règlement général de la BRVM, articles 44 à 46 (version du 1er juillet 2022). Un ordre sans indication de limite est rejeté. D’autres conditions existent sur d’autres marchés (meilleure limite, exécuté ou éliminé) : demandez à votre SGI ce qu’elle propose."}},{"type":"cas","titre":"Mise en situation : acheter 5 000 actions","contenu":"Carnet fictif, à but pédagogique. Les vendeurs proposent les quantités ci-dessous. Le cours affiché n’est pas forcément le prix auquel vous achèterez : tout dépend des quantités disponibles en face de vous.","tableau":{"colonnes":["Prix vendeur","Quantité proposée"],"lignes":[["3 280 FCFA","3 500"],["3 290 FCFA","4 500"],["3 300 FCFA","5 500"]],"note":"Carnet fictif : les quantités et les prix ne décrivent aucune valeur réelle."},"formules":[{"nom":"Ordre au mieux pour 5 000 titres","expression":"(3 500 × 3 280 + 1 500 × 3 290) ÷ 5 000","exemple":"Prix moyen : 3 283 FCFA, au-dessus du meilleur prix affiché"},{"nom":"Ordre à cours limité à 3 270 FCFA","expression":"Aucun vendeur à 3 270 FCFA ou moins","exemple":"Rien n’est exécuté : l’ordre attend selon sa validité"},{"nom":"Tout ou rien : 10 000 titres limités à 3 290 FCFA","expression":"3 500 + 4 500 = 8 000 titres disponibles à ce prix ou moins","exemple":"Moins que les 10 000 demandés : aucune exécution"}],"etapes":[{"titre":"Le sens","detail":"Achat ou vente ?"},{"titre":"La quantité","detail":"Combien de titres ?"},{"titre":"Le prix","detail":"Au mieux ou limité, et à quelle limite ?","cle":true},{"titre":"Le carnet","detail":"Quelles quantités sont disponibles en face ?"},{"titre":"La validité","detail":"Jour, mensuel, à exécution ou date limite ?"}],"etapes_style":"frise","simulation":{"type":"carnet","niveaux":[{"prix":3280,"quantite":3500},{"prix":3290,"quantite":4500},{"prix":3300,"quantite":5500}],"quantite_defaut":5000,"codes":["SNTS","SGBC","ORAC","PALC","SPHC"]}},{"type":"importance","titre":"Une action perd 20 % : la méthode en trois étapes","contenu":"Exemple : achetée 5 000 FCFA, l’action cote 4 000 FCFA quelques semaines plus tard, soit −20 %. Une baisse doit déclencher une analyse, pas une réaction.","etapes":[{"titre":"Vérifier l’actualité","detail":"Résultats publiés, changement de direction, perte d’un marché, réduction du dividende : la baisse vient-elle de l’entreprise, ou de tout le marché ?"},{"titre":"Relire les fondamentaux","detail":"Chiffre d’affaires, résultat net, dette, trésorerie, dividende soutenable, perspectives."},{"titre":"Décider sans précipitation","detail":"Conserver si les fondamentaux tiennent ; réduire si la ligne pèse trop ou si les perspectives se dégradent ; vendre si les raisons de l’achat ne tiennent plus.","cle":true}],"points":[{"titre":"Une baisse n’est pas une affaire automatique","detail":"Une société dont les comptes se dégradent peut continuer de baisser."}]},{"type":"piege","titre":"L’épargne de précaution, et les erreurs qui coûtent cher","contenu":"Votre première protection est financière : ne placez jamais en Bourse votre épargne de précaution (3 à 6 mois de dépenses essentielles).\nVotre deuxième protection est la diversification : limitez chaque société à 20 % et chaque secteur à 35 % de votre portefeuille.\nVotre troisième protection est la discipline d’exécution : utilisez des ordres à cours limité et consultez le score de liquidité avant d’acheter.","formules":[{"nom":"Épargne de précaution","expression":"Dépenses mensuelles essentielles × 3 à 6 mois","exemple":"250 000 × 6 = 1 500 000 FCFA, à garder hors du portefeuille boursier"}],"points":[{"titre":"Investir son épargne d’urgence","detail":"Un imprévu oblige alors à vendre pendant une baisse."},{"titre":"Vendre dans la panique","detail":"Un cours qui baisse ne dit pas, à lui seul, que l’entreprise s’est affaiblie."},{"titre":"Tout concentrer sur une valeur","detail":"Un seul problème touche alors une grande partie du capital."},{"titre":"Ignorer la liquidité","detail":"Un ordre au mieux sur une valeur peu échangée peut s’exécuter à un prix défavorable."},{"titre":"Acheter seulement pour le dividende","detail":"Un rendement élevé peut cacher des résultats qui se dégradent."},{"titre":"Suivre les rumeurs","detail":"Décider sur des informations vérifiables : comptes, communiqués officiels, avis de la BRVM."}]},{"type":"retenir","titre":"Votre check-list avant le premier achat","contenu":"Un investisseur discipliné ne prédit pas les baisses : il a une méthode pour les traverser. Si l’une de ces conditions manque, prenez le temps de la remplir avant de passer votre ordre.","points":[{"titre":"Mon épargne de précaution est constituée","detail":"Trois à six mois de dépenses essentielles, disponibles."},{"titre":"Mon horizon est long","detail":"Je peux laisser cet argent investi plusieurs années et accepter les variations."},{"titre":"J’ai vérifié la liquidité de la valeur","detail":"Volumes, fréquence des échanges, carnet d’ordres."},{"titre":"J’ai étudié l’entreprise","detail":"Dernier rapport annuel ou dernières publications."},{"titre":"Je sais quel ordre je passe","detail":"À cours limité si la valeur s’échange peu ; validité choisie, pas subie."},{"titre":"Trois risques, trois protections","detail":"Marché, entreprise, liquidité ; diversifier, investir longtemps, se former."}]}],"charts":[],"quiz":[{"question":"Pourquoi ne faut-il pas investir son épargne d’urgence en bourse ?","options":["Parce que les dividendes y sont imposés à la source","Parce que la bourse est réservée aux résidents ivoiriens","Parce qu’il faudrait peut-être vendre en pleine baisse","Parce que les SGI refusent les petits montants"],"correct":2,"explication":"Les actions peuvent perdre de la valeur à court terme. Si un imprévu survient, vous pourriez devoir vendre à perte. L’épargne de précaution doit rester disponible, à l’écart des variations de la bourse."},{"question":"Votre revenu de dividendes vient à parts égales de cinq sociétés. L’une divise son dividende par deux. De combien baisse votre revenu total ?","options":["−50 %","−20 %","−10 %","−5 %"],"correct":2,"explication":"Chaque société pèse 20 % du revenu. La moitié de 20 %, c’est 10 % du revenu total."},{"question":"Quel risque la diversification réduit-elle le plus directement ?","options":["Le risque de marché","Le risque propre à une entreprise","Le risque de change","Tous les risques à la fois"],"correct":1,"explication":"Répartir entre plusieurs sociétés limite l’effet d’une mauvaise nouvelle sur l’une d’elles. Une baisse générale du marché, elle, touche toutes les lignes."},{"question":"Qu’appelle-t-on le risque de liquidité ?","options":["La perte de valeur due à l’inflation chaque année","La difficulté à vendre sans faire baisser le prix","La faillite d’une société cotée","La variation du franc CFA face au dollar"],"correct":1,"explication":"Sur une valeur peu échangée, il peut y avoir peu d’acheteurs : il faut alors attendre, ou accepter un prix plus bas."},{"question":"Vos dépenses mensuelles essentielles sont de 200 000 FCFA. Combien prévoir pour six mois d’épargne de précaution ?","options":["600 000 FCFA","1 200 000 FCFA","2 000 000 FCFA","200 000 FCFA"],"correct":1,"explication":"200 000 × 6 = 1 200 000 FCFA, à garder disponibles et séparés du portefeuille boursier."},{"question":"Vous passez un ordre d’achat à cours limité à 3 270 FCFA ; le vendeur le moins cher demande 3 280 FCFA. Que se passe-t-il ?","options":["L’ordre est exécuté tout de suite à 3 280 FCFA","L’ordre attend un vendeur à 3 270 FCFA ou moins","L’ordre est exécuté à 3 270 FCFA, quoi qu’il arrive ensuite","La BRVM rejette l’ordre"],"correct":1,"explication":"Un ordre à cours limité ne s’exécute jamais au-delà de sa limite. Il reste en attente pendant sa durée de validité."},{"question":"Que signifie un ordre « tout ou rien » ?","options":["Il est exécuté au meilleur prix disponible","Il ne peut pas être servi partiellement","Il reste valable trois mois","Il n’a pas de limite de prix"],"correct":1,"explication":"Le règlement général de la BRVM définit l’ordre « tout ou rien » comme un ordre qui ne peut pas être répondu partiellement."},{"question":"Vous ne précisez pas la durée de validité de votre ordre. Comment est-il considéré ?","options":["Mensuel, jusqu’à la fin du mois en cours","Jour : valable une seule séance","À exécution, valable pendant trois mois","Annulé avant même d’être transmis"],"correct":1,"explication":"Selon le règlement général de la BRVM, un ordre sans indication de validité est réputé « jour »."},{"question":"Combien de valeurs sur les 48 cotées atteignent la classe A de liquidité au 23 novembre 2026 ?","options":["4 valeurs","24 valeurs","36 valeurs","Toutes les 48 valeurs"],"correct":0,"explication":"Seules 4 valeurs (SNTS, SGBC, BBGC, BOAC) atteignent la classe A, ce qui impose de vérifier la liquidité avant tout ordre important."},{"question":"Pourquoi un écart achat/vente de 8,99 % sur un titre peu liquide pèse-t-il sur votre rendement ?","options":["Parce qu’il est remboursé par la SGI","Parce qu’acheter au prix vendeur puis revendre au prix acheteur coûte d’emblée près de 9 %","Parce que l’IRVM passe à 8,99 %","Parce que le dividende est doublé"],"correct":1,"explication":"Un spread large agit comme un coût d’entrée/sortie immédiat : il faut plusieurs années de dividende ou de hausse pour le compenser."},{"question":"Quel recul réel a subi SCRC sur 52 semaines au 23 novembre 2026 depuis son plus-haut ?","options":["−5 %","−15 %","−68,6 %","0 %"],"correct":2,"explication":"SCRC est passée de 3 920 FCFA à 1 230 FCFA (−68,6 %), illustrant qu’une action individuelle peut perdre plus de la moitié de sa valeur."}],"qcm":{"question":"Pourquoi ne faut-il pas investir son épargne d’urgence en bourse ?","options":["Parce que les dividendes y sont imposés à la source","Parce que la bourse est réservée aux résidents ivoiriens","Parce qu’il faudrait peut-être vendre en pleine baisse","Parce que les SGI refusent les petits montants"],"correct":2,"explication":"Les actions peuvent perdre de la valeur à court terme. Si un imprévu survient, vous pourriez devoir vendre à perte. L’épargne de précaution doit rester disponible, à l’écart des variations de la bourse."},"liens":[{"label":"Classement de liquidité","href":"/liquidite"},{"label":"Espace dividendes","href":"/dividendes"},{"label":"Choisir sa SGI","href":"/comparateur-sgi"}],"module":"Module 2 — Dividendes et investissement pratique","nouveaute":{"type":"mis_a_jour","depuis":"2026-11-24"}}$L6_M23_2$::jsonb
  );

  -- Position 7 (lecon8-scolarite.json)
  IF NOT ((v_content->'lessons'->7->>'titre') LIKE 'Leçon 8 — %') THEN
    RAISE EXCEPTION 'Migration 0269 interrompue : leçon en position 7 inattendue (%)', v_content->'lessons'->7->>'titre';
  END IF;
  v_content := jsonb_set(
    v_content,
    '{lessons,7}',
    (v_content->'lessons'->7) || $L7_M23_3${"titre":"Leçon 8 — Cas pratique : financer la scolarité de vos enfants","image":{"url":"https://images.pexels.com/photos/10646406/pexels-photo-10646406.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","alt":"Salle de classe vide, tables alignées et sacs d’élèves","credit":"Photo : Ron Lach / Pexels"},"categorie":"income","duree_min":10,"sous_titre":"Partir d’un objectif daté, mesurer l’effort réel, et laisser le temps travailler.","resume":"Les études supérieures se préparent des années à l’avance : c’est un objectif idéal pour un placement de long terme.\nCette leçon chiffre honnêtement ce qu’un capital de départ peut produire, et ce qu’il ne suffit pas à financer seul.","avertissement":"Ceci n’est pas un conseil en investissement. Les performances passées ne préjugent pas des performances futures. Investir en actions comporte un risque de perte en capital.","sections":[{"type":"definition","titre":"Un objectif connu à l’avance","contenu":"Financer une scolarité future demande deux ingrédients : un horizon long (8 à 12 ans) pour laisser travailler la capitalisation, et un calendrier d’encaissement cohérent avec la rentrée.\nBonne nouvelle à la BRVM : la majorité des dividendes sont versés entre mai et septembre, juste avant les frais de rentrée d’octobre.\nSur l’exercice 2025, BOAB a payé le 2026-05-26, PALC le 2026-06-29, STBC le 2026-08-13 et ABJC le 2026-09-30.","flux":[{"titre":"Objectif daté","detail":"Un budget et une année d’entrée en études.","icone":"calendrier"},{"titre":"Capital investi","detail":"Un premier achat, puis des versements réguliers.","icone":"piece"},{"titre":"Dividendes réinvestis","detail":"Ils achètent de nouvelles actions chaque année.","icone":"graphique"},{"titre":"Revenu à l’échéance","detail":"Les dividendes et le capital financent les études.","icone":"paiement"}]},{"type":"cas","titre":"Ce que 200 000 FCFA peuvent produire","contenu":"Pour construire un revenu annuel cible, partez toujours du rendement net d’IRVM (12 % en Côte d’Ivoire) et déduisez environ 1 % de frais de courtage à chaque achat.\nAvec un rendement net hypothétique de 8 %, viser 1 000 000 FCFA par an demande un capital de 12 500 000 FCFA (1 000 000 ÷ 0,08).\nÀ défaut de ce capital dès le départ, un versement mensuel régulier combiné au réinvestissement des dividendes permet de s’en rapprocher année après année.","simulation":{"type":"reinvestissement","actions":40,"dpa":400,"cours":5000,"croissance_pct":5,"annees":10},"graphiques":[{"type":"bar","titre":"Calendrier réel des paiements de dividendes (mai à septembre 2026, FCFA net/action)","reel":true,"note":"Sources : Calendrier officiel des dividendes BRVM (ex. 2025). Montants nets versés.","labels":["BOAB (mai)","PALC (juin)","SGBC (août)","STBC (août)","ABJC (sept.)"],"valeurs":[585,441.4,2293.28,1707.2,201.52]}]},{"type":"cas","titre":"Le capital nécessaire, sans détour","contenu":"Pour qu’un portefeuille verse 1 000 000 FCFA par an, montant pris comme hypothèse pour une année d’études, il faut diviser ce revenu par le rendement.\nLe résultat montre pourquoi l’épargne régulière et le temps font l’essentiel du travail.","formules":[{"nom":"Capital nécessaire","expression":"Revenu annuel visé ÷ Rendement","exemple":"1 000 000 ÷ 8 % = 12 500 000 FCFA"}],"simulation":{"type":"objectif","revenu_cible":1000000,"rendements_pct":[6,8,10]}},{"type":"cas","reel":true,"titre":"Sur la BRVM : ce que rapportent 100 actions","contenu":"Les mêmes calculs s’appliquent aux valeurs cotées. Le tableau montre, pour quatre sociétés, le dernier dividende enregistré, le cours de la dernière séance et le revenu de 100 actions.","donnees_reelles":{"vue":"rendement","codes":["SNTS","SIBC","ORAC","BOAB"],"actions":100}},{"type":"importance","titre":"Un plan en cinq étapes","contenu":"À l’approche de l’échéance (les 2 à 3 dernières années avant le paiement des frais universitaires), il faut sécuriser progressivement le capital accumulé.\nVendre une partie des actions lors des bonnes périodes pour basculer vers des obligations d’État UEMOA (6,15 % à 6,30 % par an) ou des dépôts à terme évite d’être forcé de vendre en pleine baisse boursière.","etapes_style":"frise","etapes":[{"titre":"Fixer le budget et la date","detail":"Combien, et pour quelle rentrée."},{"titre":"Ouvrir un compte titres","detail":"Auprès d’une SGI agréée."},{"titre":"Investir régulièrement","detail":"Chaque mois ou chaque trimestre, même un petit montant.","cle":true},{"titre":"Réinvestir les dividendes","detail":"Jusqu’à quelques années de l’échéance."},{"titre":"Sécuriser avant l’échéance","detail":"Réduire la part en actions deux à trois ans avant les études."}],"graphiques":[{"type":"bar","titre":"Exemple pédagogique : trajectoire d’un capital de 1 000 FCFA à 10 %/an sur 10 ans","reel":false,"note":"Exemple pédagogique à taux composé constant (10 %/an), hors frais et impôts.","labels":["Année 0","Année 3","Année 5","Année 8","Année 10"],"valeurs":[1000,1331,1611,2144,2594]}]},{"type":"piege","titre":"Les erreurs à éviter","contenu":"Le temps est l’allié de ce projet : chaque année perdue réduit l’effet du réinvestissement.","formules":[{"nom":"Valeur future d’un montant placé","expression":"Montant × (1 + taux) ^ années","exemple":"1 000 × 1,10 ^ 10 ≈ 2 594 FCFA"}],"points":[{"titre":"Attendre le moment parfait","detail":"Il n’existe pas. Commencer tôt, même petit, compte davantage que choisir le bon jour."},{"titre":"Surestimer le rendement","detail":"Un dividende peut baisser. Construisez votre plan sur une hypothèse prudente."},{"titre":"Tout miser sur un seul titre","detail":"Un projet de dix ans traversera de mauvaises années : répartissez sur plusieurs valeurs."},{"titre":"Rester tout en actions jusqu’au dernier jour","detail":"Une baisse juste avant la rentrée obligerait à vendre au mauvais moment."}],"simulation":{"type":"valeur_future","consigne":"Ajoutez un versement mensuel ou un capital visé : le simulateur compare aussi avec un départ trois ans plus tard.","capital_initial":200000,"versement_mensuel":0,"taux_pct":8,"annees":10,"objectif":0}},{"type":"retenir","titre":"L’essentiel","contenu":"Cinq idées à garder en tête.","points":[{"titre":"Un objectif daté convient bien à la bourse","detail":"À condition de commencer des années à l’avance."},{"titre":"Un capital de départ seul ne suffit pas","detail":"Les versements réguliers font l’essentiel de l’effort."},{"titre":"Capital nécessaire = revenu visé ÷ rendement","detail":"À 8 %, 1 000 000 FCFA par an demandent 12 500 000 FCFA."},{"titre":"Réinvestir multiplie les actions","detail":"Chaque dividende réinvesti rapporte à son tour."},{"titre":"Sécuriser avant l’échéance","detail":"On réduit le risque quand la date approche."}]}],"quiz":[{"question":"Vous détenez 200 actions versant 1 200 FCFA et 100 actions versant 400 FCFA. Quel est votre revenu annuel de dividendes ?","options":["160 000 FCFA","280 000 FCFA","320 000 FCFA","1 600 FCFA"],"correct":1,"explication":"(200 × 1 200) + (100 × 400) = 240 000 + 40 000 = 280 000 FCFA."},{"question":"Quel capital faut-il pour recevoir 1 000 000 FCFA par an, à 8 % de rendement hypothétique ?","options":["8 000 000 FCFA","12 500 000 FCFA","80 000 FCFA","125 000 000 FCFA"],"correct":1,"explication":"Capital = revenu visé ÷ rendement : 1 000 000 ÷ 8 % = 12 500 000 FCFA."},{"question":"Pourquoi réduire la part en actions quelques années avant les études ?","options":["Parce que les dividendes cessent avant l’échéance","Pour ne pas vendre en baisse au mauvais moment","Parce que les SGI ferment les comptes des parents","Pour payer moins de frais de courtage"],"correct":1,"explication":"Près de l’échéance, on ne peut plus attendre qu’un cours remonte : sécuriser progressivement évite de vendre au plus bas."},{"question":"1 000 FCFA placés à 10 % par an pendant 10 ans deviennent environ :","options":["2 000 FCFA","2 594 FCFA","1 100 FCFA","10 000 FCFA"],"correct":1,"explication":"1 000 × 1,10 ^ 10 ≈ 2 594 FCFA : les gains de chaque année produisent à leur tour des gains."},{"question":"Dans ce projet, à quoi sert le réinvestissement des dividendes ?","options":["À payer les frais de scolarité chaque année","À accroître les dividendes futurs","À éviter tout risque de baisse du capital","À garantir le rendement du projet"],"correct":1,"explication":"Chaque dividende réinvesti achète de nouvelles actions, qui rapportent à leur tour : le revenu grandit d’année en année."},{"question":"Pourquoi la période mai–septembre de la BRVM convient-elle bien à un projet de rentrée scolaire ?","options":["Parce que la Bourse est fermée de mai à septembre","Parce que la majorité des dividendes sont payés entre mai et septembre, avant la rentrée","Parce que les frais SGI sont supprimés en été","Parce que l’IRVM est remboursé en septembre"],"correct":1,"explication":"Le gros des détachements et paiements de dividendes BRVM a lieu entre mai et septembre, alimentant le compte espèces avant octobre."},{"question":"Quelle poche d’actifs privilégier à 1 ou 2 ans de l’entrée à l’université pour sécuriser le capital ?","options":["Des actions de classe D très volatiles","Des obligations d’État UEMOA ou de l’épargne bancaire sécurisée","Un seul titre cyclique","Des crypto-actifs à fort levier"],"correct":1,"explication":"À court terme (1–2 ans), la priorité est la préservation du capital : obligations courtes ou épargne garantie."},{"question":"Que permet le réinvestissement des dividendes pendant les 6 à 8 premières années du projet ?","options":["D’acheter de nouvelles actions qui produiront à leur tour des dividendes","De réduire le nombre d’actions détenues","D’éviter toute variation de cours","De supprimer le risque sectoriel"],"correct":0,"explication":"Chaque dividende réinvesti augmente le nombre d’actions génératrices de revenus futurs (effet boule de neige)."},{"question":"Quel risque guette un parent qui reste investi à 100 % en actions jusqu’au mois de la rentrée ?","options":["Devoir vendre ses titres en pleine baisse temporaire du marché","Recevoir deux fois le même dividende","Ne pas pouvoir payer par virement","Payer un IRVM de 0 %"],"correct":0,"explication":"Un repli boursier de −20 % à −30 % juste avant la rentrée réduirait le budget disponible s’il n’a pas été sécurisé à l’avance."}],"qcm":{"question":"Vous détenez 200 actions versant 1 200 FCFA et 100 actions versant 400 FCFA. Quel est votre revenu annuel de dividendes ?","options":["160 000 FCFA","280 000 FCFA","320 000 FCFA","1 600 FCFA"],"correct":1,"explication":"(200 × 1 200) + (100 × 400) = 240 000 + 40 000 = 280 000 FCFA."},"liens":[{"label":"Simulateur de budget","href":"/simulateur-budget"},{"label":"Espace dividendes","href":"/dividendes"}],"module":"Module 2 — Dividendes et investissement pratique","nouveaute":{"type":"mis_a_jour","depuis":"2026-11-24"},"charts":[]}$L7_M23_3$::jsonb
  );

  -- Position 8 (lecon9-strategies.json)
  IF NOT ((v_content->'lessons'->8->>'titre') LIKE 'Leçon 9 — %') THEN
    RAISE EXCEPTION 'Migration 0269 interrompue : leçon en position 8 inattendue (%)', v_content->'lessons'->8->>'titre';
  END IF;
  v_content := jsonb_set(
    v_content,
    '{lessons,8}',
    (v_content->'lessons'->8) || $L8_M23_4${"titre":"Leçon 9 — Trois stratégies d’investissement à la BRVM","image":{"url":"https://images.pexels.com/photos/7947707/pexels-photo-7947707.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200","alt":"Rapport financier imprimé avec graphiques, loupe et calculatrice","credit":"Photo : RDNE Stock project / Pexels"},"categorie":"general","duree_min":10,"sous_titre":"Valeur, revenu ou croissance : choisir une approche, et l’horizon qui va avec.","resume":"Trois grandes approches structurent l’investissement en actions : acheter sous la valeur, viser un revenu régulier, ou miser sur la croissance.\nAucune n’est gagnante en soi : la bonne dépend de votre objectif, de votre horizon et de votre tolérance au risque.","avertissement":"Ceci n’est pas un conseil en investissement. Les performances passées ne préjugent pas des performances futures. Investir en actions comporte un risque de perte en capital.","sections":[{"type":"definition","titre":"Trois approches","contenu":"Acheter sans stratégie revient à réagir à chaque variation du jour. À la BRVM, trois approches complémentaires dominent chez les investisseurs disciplinés.\n1. La stratégie Revenu privilégie la régularité et le rendement net du dividende (ex. SGBC à 6,11 % net ou STBC à 8,37 % net).\n2. La stratégie Valeur (décote) cherche des sociétés rentables payées sous leur moyenne historique de PER ou de P/B — en vérifiant toujours qu’il ne s’agit pas d’un piège (« value trap »).\n3. La stratégie Croissance accepte un rendement immédiat plus modeste pour capter la progression durable des bénéfices et du dividende (ex. SNTS ou SGBC sur 5 ans).","points":[{"titre":"Valeur (« value »)","detail":"Acheter une société dont le cours paraît inférieur à ce qu’elle vaut, en attendant que le marché le reconnaisse.","verifier":"le PER, la rentabilité des capitaux propres et l’endettement."},{"titre":"Revenu (« income »)","detail":"Constituer un portefeuille de sociétés qui versent un dividende régulier, et réinvestir ce revenu.","verifier":"la régularité du dividende sur au moins cinq exercices."},{"titre":"Croissance (« growth »)","detail":"Miser sur des sociétés dont l’activité progresse vite, quitte à recevoir peu de dividendes et à subir plus de volatilité.","verifier":"la progression du chiffre d’affaires et des bénéfices sur plusieurs années."}],"graphiques":[{"type":"line","titre":"Croissance régulière du dividende net sur 5 ans : SNTS vs SGBC (base 100 en 2021)","reel":true,"note":"Sources : BRVM (calendrier officiel 2025) et historiques 2021–2024 rebasés à 100 en 2021.","labels":["2021","2022","2023","2024","2025"],"valeurs":[],"series":[{"nom":"SNTS (base 100)","valeurs":[100,107,113,119,124],"type":"line","axe":"gauche"},{"nom":"SGBC (base 100)","valeurs":[100,110,154,163,228],"type":"line","axe":"gauche"}]}]},{"type":"importance","titre":"Pourquoi choisir avant d’acheter","contenu":"Beaucoup d’investisseurs achètent ce dont on parle, vendent dès que ça baisse et rachètent quand ça monte. Ils manquent les dividendes et cristallisent leurs pertes.\nUne stratégie fixée à l’avance protège de la peur et de l’euphorie : elle donne un critère clair à chaque décision."},{"type":"cas","reel":true,"titre":"Revenu : des dividendes à suivre dans le temps","contenu":"Le PER (Price-to-Earnings Ratio) rapporte le cours de l’action au bénéfice par action (BPA). Un PER de 8 signifie qu’au rythme actuel, il faut 8 ans de bénéfices pour égaler le prix payé.\nAttention au piège du PER bas : si le bénéfice vient d’un gain exceptionnel ou s’il est en train de chuter, un PER apparemment bon marché devient cher l’année suivante.\nÀ la BRVM, comparez toujours le PER d’une banque avec celui des autres banques, et le ROE (rentabilité des capitaux propres) avec la solidité du bilan.","donnees_reelles":{"vue":"historique","codes":["SNTS","BOAB","SGBC","SIBC"]}},{"type":"cas","titre":"Valeur : lire le PER","contenu":"Le PER compare le prix d’une action au bénéfice qu’elle génère. Un PER de 8 signifie que l’on paie l’action 8 fois son bénéfice annuel.\nUn PER bas peut signaler une décote à saisir, ou une société en difficulté. Il se compare toujours à celui du secteur et à son propre historique.","formules":[{"nom":"PER","expression":"Cours de l’action ÷ Bénéfice par action","exemple":"10 000 ÷ 1 250 = 8"}],"simulation":{"type":"per","consigne":"Calculez un PER sur l’exemple de la leçon, puis sur une valeur cotée, à partir de ses derniers comptes publiés.","cours":10000,"bpa":1250,"croissance_pct":0,"annees":3,"codes":["SNTS","SGBC","BOAB"]}},{"type":"importance","titre":"Associer stratégie et horizon","contenu":"En pratique, beaucoup d’investisseurs combinent un socle « Revenu / Qualité » (60 à 70 % du portefeuille) avec une poche « Valeur ou Croissance » (30 à 40 %).\nQuelle que soit la stratégie, donnez-lui un horizon cohérent : 5 ans minimum pour juger une valeur de rendement ou de croissance, et un suivi semestriel des comptes publiés.","tableau":{"colonnes":["Stratégie","Objectif","Horizon","Profil"],"lignes":[["Valeur","Acheter sous la valeur","3 à 5 ans","Patient et analytique"],["Revenu","Encaisser un revenu régulier","5 ans et plus","Recherche un revenu régulier"],["Croissance","Viser une plus-value","5 ans et plus","Tolérant à la volatilité"]],"note":"Repères pédagogiques, pas des règles : votre situation personnelle prime."}},{"type":"piege","titre":"Les erreurs à éviter","contenu":"Les mêmes erreurs reviennent quand la stratégie n’est pas tenue.","points":[{"titre":"Mélanger les approches sans cohérence","detail":"Acheter une action pour son dividende, puis la vendre trois mois après parce que le cours n’a pas bougé."},{"titre":"Choisir sur le seul rendement","detail":"Un rendement très élevé peut annoncer une baisse du dividende ou refléter un cours en chute."},{"titre":"Confondre PER bas et bonne affaire","detail":"Un PER bas peut traduire des bénéfices qui vont reculer."},{"titre":"Suivre la rumeur","detail":"Ce dont tout le monde parle est souvent déjà dans le prix."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Cinq idées à garder en tête.","points":[{"titre":"Trois approches : valeur, revenu, croissance","detail":"Chacune a ses critères et son horizon."},{"titre":"La stratégie revenu demande le moins de suivi quotidien","detail":"Elle repose sur des dividendes votés chaque année, pas sur le cours du jour."},{"titre":"PER = cours ÷ bénéfice par action","detail":"À comparer au secteur, jamais seul."},{"titre":"Une stratégie se juge sur son horizon","detail":"Cinq ans pour une action de rendement, pas trois mois."},{"titre":"Le passé ne garantit pas la suite","detail":"Un dividende en hausse se revérifie chaque année."}]}],"quiz":[{"question":"Quelle stratégie vise d’abord un revenu régulier ?","options":["La stratégie valeur","La stratégie revenu","La stratégie croissance","Le trading quotidien"],"correct":1,"explication":"La stratégie revenu vise des dividendes réguliers, encaissés ou réinvestis. Elle demande peu de suivi quotidien."},{"question":"Une action cote 12 000 FCFA et son bénéfice par action est de 1 500 FCFA. Quel est son PER ?","options":["5","8","18","0,125"],"correct":1,"explication":"PER = cours ÷ bénéfice par action = 12 000 ÷ 1 500 = 8."},{"question":"Un PER très bas signifie-t-il toujours une bonne affaire ?","options":["Oui, dans tous les cas","Non : les bénéfices peuvent reculer","Oui, dès qu’il est inférieur à 20","Non, un PER bas est toujours mauvais signe"],"correct":1,"explication":"Un PER bas peut signaler une décote… ou une société en difficulté. Il se compare au secteur et à l’historique de la société."},{"question":"Sur quel horizon juger une action achetée pour son dividende ?","options":["Une semaine","Trois mois","Cinq ans environ","Un jour"],"correct":2,"explication":"Une stratégie de revenu se juge sur la régularité des dividendes, donc sur plusieurs années."},{"question":"Quelle stratégie accepte de recevoir peu de dividendes en échange d’un potentiel de plus-value ?","options":["La stratégie valeur","La stratégie revenu","La stratégie croissance","Aucune"],"correct":2,"explication":"La stratégie croissance mise sur la progression de l’activité et du cours, au prix d’une volatilité plus forte."},{"question":"Qu’est-ce qu’un « value trap » (piège de valeur) en analyse boursière ?","options":["Une action chère qui double chaque mois","Une action à PER très bas dont les bénéfices et l’activité continuent de se dégrader","Un dividende payé deux fois","Un titre obligataire d’État"],"correct":1,"explication":"Un PER bas n’est une opportunité que si les bénéfices sont durables ; s’ils chutent, le cours peut continuer de baisser."},{"question":"Sur 5 exercices (2021–2025), comment a évolué le dividende net de SGBC ?","options":["Il a été supprimé","Il est passé d’environ 1 005 FCFA à 2 293 FCFA (+128 %)","Il a été divisé par deux","Il est resté figé à 500 FCFA"],"correct":1,"explication":"Le dividende net de SGBC est passé de 1 004,93 FCFA (2021) à 2 293,28 FCFA (2025), illustrant une dynamique bénéficiaire soutenue."},{"question":"Pourquoi faut-il comparer le PER d’une banque uniquement à d’autres banques ?","options":["Parce que les banques n’ont pas de clients","Parce que leur structure comptable (PNB, levier, coût du risque) diffère des sociétés industrielles","Parce que le PER des banques est toujours égal à 1","Parce que la BRVM interdit de comparer deux secteurs"],"correct":1,"explication":"Les banques et les industries ont des modèles économiques et des ratios de bilan incomparables directement : comparez toujours au sein du même secteur."},{"question":"Quel indicateur complète le PER pour vérifier la rentabilité réelle des capitaux investis ?","options":["Le ROE (Return on Equity)","Le numéro ISIN","L’heure de clôture","Le nombre de pages du rapport"],"correct":0,"explication":"Le ROE (résultat net ÷ capitaux propres) mesure la rentabilité créée pour les actionnaires ; il éclaire si un P/B ou PER est justifié."}],"qcm":{"question":"Quelle stratégie vise d’abord un revenu régulier ?","options":["La stratégie valeur","La stratégie revenu","La stratégie croissance","Le trading quotidien"],"correct":1,"explication":"La stratégie revenu vise des dividendes réguliers, encaissés ou réinvestis. Elle demande peu de suivi quotidien."},"liens":[{"label":"Screener des actions","href":"/screener"},{"label":"Espace dividendes","href":"/dividendes"}],"module":"Module 3 — Stratégies et compte","nouveaute":{"type":"mis_a_jour","depuis":"2026-11-24"},"charts":[]}$L8_M23_4$::jsonb
  );

  -- Position 9 (lecon10-diaspora.json)
  IF NOT ((v_content->'lessons'->9->>'titre') LIKE 'Leçon 10 — %') THEN
    RAISE EXCEPTION 'Migration 0269 interrompue : leçon en position 9 inattendue (%)', v_content->'lessons'->9->>'titre';
  END IF;
  v_content := jsonb_set(
    v_content,
    '{lessons,9}',
    (v_content->'lessons'->9) || $L9_M23_5${"titre":"Leçon 10 — Investir depuis l’étranger (diaspora)","image":{"url":"https://images.pexels.com/photos/6564816/pexels-photo-6564816.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","alt":"Carte de l’Afrique de l’Ouest et du Centre, avec la Côte d’Ivoire, le Mali, le Burkina Faso et le Niger","credit":"Photo : Nothing Ahead / Pexels"},"categorie":"general","duree_min":9,"sous_titre":"Ouvrir un compte à distance, transférer ses fonds, recevoir ses dividendes.","resume":"Il n’est pas nécessaire de vivre dans l’UEMOA pour investir à la BRVM : de nombreuses SGI ouvrent des comptes à distance.\nCette leçon décrit le parcours, le change et les précautions propres aux investisseurs de la diaspora.","avertissement":"Ceci n’est pas un conseil en investissement. Les performances passées ne préjugent pas des performances futures. Investir en actions comporte un risque de perte en capital.","sections":[{"type":"definition","titre":"Le parcours à distance","contenu":"Un investisseur résidant en France, en Belgique, au Canada ou aux États-Unis peut investir à la BRVM sans résidence fiscale dans l’UEMOA, en ouvrant un compte-titres auprès d’une SGI agréée par l’AMF-UMOA.\nPour la zone euro, la parité fixe garantie par la BCEAO est de 1 € = 655,957 FCFA : il n’y a aucun risque de change entre l’euro et le franc CFA.\nEn revanche, depuis le dollar américain (USD), canadien (CAD) ou la livre sterling (GBP), le taux de change varie chaque jour face à l’euro et donc face au FCFA.","flux":[{"titre":"Banque à l’étranger","detail":"Votre compte dans le pays de résidence.","icone":"entreprise"},{"titre":"Virement international","detail":"Vers le compte de votre SGI.","icone":"paiement"},{"titre":"Compte chez une SGI","detail":"Agréée par l’AMF-UMOA.","icone":"decision"},{"titre":"Achat d’actions","detail":"En ligne, quand la SGI le propose.","icone":"graphique"},{"titre":"Dividendes","detail":"Conservés en FCFA ou virés à l’étranger.","icone":"piece"}]},{"type":"importance","titre":"Le change euro – franc CFA","contenu":"Quarante SGI agréées opèrent dans sept pays de l’UEMOA (20 en Côte d’Ivoire, 6 au Sénégal, 5 au Bénin, 4 au Burkina Faso…). Plusieurs acceptent l’ouverture à distance avec pièces certifiées.\nVérifiez trois points avant d’envoyer vos fonds : l’agrément AMF-UMOA, les frais de virement international entrant/sortant, et le délai de rapatriement des dividendes.","formules":[{"nom":"Conversion","expression":"Montant en FCFA = Montant en euros × 655,957","exemple":"500 € × 655,957 ≈ 327 979 FCFA"}],"simulation":{"type":"change","consigne":"Renseignez les frais de votre banque : la parité ne bouge pas, mais les frais réduisent ce qui arrive sur le compte.","montant_eur":500,"frais_pct":0,"frais_fixes_eur":0,"cours_action":0},"graphiques":[{"type":"bar","titre":"Implantation des 40 SGI agréées par pays UEMOA (accès à distance)","reel":true,"note":"Sources : Annuaire officiel des SGI BRVM / AMF-UMOA (2026).","labels":["CI","SN","BJ","BF","ML","NE","TG"],"valeurs":[20,6,5,4,3,1,1]}]},{"type":"importance","titre":"Documents et délais","contenu":"Chaque SGI fixe sa liste de pièces. Les plus courantes sont les suivantes.","points":[{"titre":"Une pièce d’identité valide","detail":"Carte d’identité ou passeport, parfois avec une copie certifiée."},{"titre":"Un justificatif de résidence","detail":"Récent, dans votre pays d’accueil."},{"titre":"Le formulaire d’ouverture signé","detail":"Souvent transmis sous forme numérisée."},{"titre":"Un premier virement","detail":"Comptez de quelques jours à quelques semaines selon la banque et la SGI.","verifier":"les frais de virement facturés par votre banque et par la SGI."}]},{"type":"importance","titre":"Recevoir ses dividendes","contenu":"Sur le plan fiscal, l’IRVM (ex. 12 % en Côte d’Ivoire) est retenu à la source avant le versement du dividende sur votre compte espèces SGI.\nSelon votre pays de résidence et l’existence d’une convention fiscale (comme entre la France et la Côte d’Ivoire ou le Sénégal), ces revenus peuvent devoir être déclarés localement avec crédit d’impôt.\nConservez chaque avis d’opéré et relevé annuel de votre SGI pour justifier l’origine des fonds lors du rapatriement vers votre banque étrangère."},{"type":"cas","reel":true,"titre":"Sur la BRVM : ce que rapportent 50 actions","contenu":"Le tableau montre, pour quatre valeurs, le dernier dividende enregistré et le revenu de 50 actions. Pour l’exprimer en euros, divisez le montant en FCFA par 655,957.","donnees_reelles":{"vue":"rendement","codes":["SNTS","ORAC","SGBC","BOAB"],"actions":50}},{"type":"piege","titre":"Les erreurs à éviter","contenu":"Méfiez-vous des plateformes non agréées qui promettent des rendements garantis ou vendent des « actions africaines » par carte bancaire sans compte-titres SGI à votre nom.\nRègle absolue : vérifiez l’agrément AMF-UMOA de l’intermédiaire et ne virez jamais d’argent sur un compte personnel.","points":[{"titre":"Passer par une plateforme non agréée","detail":"Des sites hors UEMOA proposent des « actions africaines » sans agrément : ce sont souvent des arnaques."},{"titre":"Confier ses fonds à un intermédiaire informel","detail":"Un proche ou un « agent » qui investit à votre place n’offre aucune garantie."},{"titre":"Multiplier les petits virements","detail":"Les frais bancaires internationaux peuvent absorber le rendement des petits montants."},{"titre":"Ignorer la fiscalité du pays de résidence","detail":"Les dividendes peuvent y être déclarés et imposés."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Cinq idées à garder en tête.","points":[{"titre":"On peut investir à la BRVM depuis l’étranger","detail":"Par une SGI agréée qui ouvre des comptes à distance."},{"titre":"1 € = 655,957 FCFA","detail":"Une parité fixe : le change ne varie pas au jour le jour depuis la zone euro. Une modification de parité reste possible, comme en 1994."},{"titre":"Les dividendes peuvent rester en FCFA ou être rapatriés","detail":"Avec des frais et un délai de virement."},{"titre":"La fiscalité du pays de résidence compte","detail":"Renseignez-vous avant le premier dividende."},{"titre":"Aucun agrément, aucun dépôt","detail":"Vérifiez l’agrément de l’intermédiaire auprès de l’AMF-UMOA."}]}],"quiz":[{"question":"1 000 € correspondent à combien de francs CFA ?","options":["655 957 FCFA","65 596 FCFA","1 000 000 FCFA","6 559 570 FCFA"],"correct":0,"explication":"1 000 × 655,957 = 655 957 FCFA, selon la parité fixe entre l’euro et le franc CFA."},{"question":"Pour un investisseur résidant dans la zone euro, la parité euro – franc CFA est :","options":["Flottante, révisée chaque jour","Fixe","Indexée sur le dollar","Révisée chaque mois par la BRVM"],"correct":1,"explication":"La parité est fixe : 1 euro = 655,957 FCFA. Le change ne varie donc pas au jour le jour pour un investisseur de la zone euro ; une modification de parité reste possible, comme en 1994."},{"question":"Qui doit être agréé pour vous permettre d’investir à la BRVM depuis l’étranger ?","options":["Votre banque étrangère","La SGI, par l’AMF-UMOA","N’importe quel courtier en ligne international","Personne, aucun agrément n’est nécessaire"],"correct":1,"explication":"Seule une SGI agréée par l’AMF-UMOA peut transmettre vos ordres à la BRVM, où que vous résidiez."},{"question":"Une plateforme hors UEMOA vous propose des « actions africaines » sans agrément. Que faire ?","options":["Investir un petit montant pour tester d’abord","Ne rien déposer, vérifier l’agrément","Y investir si le rendement promis est très élevé","Demander à un proche d’investir à votre place"],"correct":1,"explication":"Sans agrément, aucun recours : ces plateformes sont une source fréquente d’arnaques visant la diaspora."},{"question":"Les dividendes perçus par un investisseur résidant à l’étranger :","options":["Sont toujours exonérés d’impôt dans tous les pays","Peuvent aussi être imposés là où vous résidez","Ne peuvent jamais être virés hors de l’UEMOA","Sont versés uniquement en euros, sans conversion"],"correct":1,"explication":"Après la retenue à la source du pays de la société, le pays de résidence peut aussi imposer le dividende, selon ses règles et les conventions fiscales."},{"question":"Un résident aux États-Unis (en USD) investissant à la BRVM est-il exposé au risque de change ?","options":["Non, le dollar est lié au FCFA à parité fixe","Oui, car le FCFA est arrimé à l’euro, pas au dollar américain","Uniquement sur les obligations","Jamais, la BRVM compense les écarts de change"],"correct":1,"explication":"La parité fixe concerne EUR/XOF (655,957). Face au USD, CAD ou GBP, le cours de change fluctue avec la paire EUR/USD."},{"question":"Pourquoi faut-il conserver les avis d’opéré et relevés annuels de votre SGI depuis l’étranger ?","options":["Pour participer au tirage au sort de la BRVM","Pour prouver l’origine fiscale des dividendes et faciliter le rapatriement bancaire","Pour supprimer les droits de garde","Pour voter deux fois en assemblée générale"],"correct":1,"explication":"Les banques étrangères et administrations fiscales exigent des justificatifs d’origine des fonds et de retenue à la source."},{"question":"Quel est le réflexe immédiat face à un démarchage promettant « 5 % par mois garantis sur la BRVM » ?","options":["Déposer une petite somme pour tester","Refuser : aucun rendement boursier n’est garanti, vérifier l’agrément AMF-UMOA","Donner ses codes bancaires","Envoyer un virement par messagerie"],"correct":1,"explication":"En bourse, les rendements ne sont jamais garantis ; toute promesse de rendement fixe mensuel élevé est un signal d’alerte majeur."},{"question":"Une SGI basée au Sénégal peut-elle exécuter vos ordres sur une société ivoirienne cotée à la BRVM ?","options":["Non, il faut une SGI par pays","Oui, la BRVM est une bourse régionale unifiée couvrant les 8 pays de l’UEMOA","Seulement pour les obligations","Uniquement le vendredi"],"correct":1,"explication":"La BRVM est un marché régional unique : toute SGI agréée par l’AMF-UMOA accède à l’ensemble des titres cotés."}],"qcm":{"question":"1 000 € correspondent à combien de francs CFA ?","options":["655 957 FCFA","65 596 FCFA","1 000 000 FCFA","6 559 570 FCFA"],"correct":0,"explication":"1 000 × 655,957 = 655 957 FCFA, selon la parité fixe entre l’euro et le franc CFA."},"liens":[{"label":"Comparateur de SGI","href":"/comparateur-sgi"},{"label":"Fiscalité des placements","href":"/fiscalite"}],"module":"Module 3 — Stratégies et compte","nouveaute":{"type":"mis_a_jour","depuis":"2026-11-24"},"charts":[]}$L9_M23_5$::jsonb
  );

  -- Position 10 (lecon11-comparaison.json)
  IF NOT ((v_content->'lessons'->10->>'titre') LIKE 'Leçon 11 — %') THEN
    RAISE EXCEPTION 'Migration 0269 interrompue : leçon en position 10 inattendue (%)', v_content->'lessons'->10->>'titre';
  END IF;
  v_content := jsonb_set(
    v_content,
    '{lessons,10}',
    (v_content->'lessons'->10) || $L10_M23_6${"titre":"Leçon 11 — BRVM ou autres placements : une comparaison objective","image":{"url":"https://images.pexels.com/photos/13208025/pexels-photo-13208025.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","alt":"Balance à plateaux en laiton posée sur une étagère","credit":"Photo : Diana ✨ / Pexels"},"categorie":"general","duree_min":10,"sous_titre":"Rendement, risque, liquidité et effort : situer la bourse dans un patrimoine.","resume":"Il n’existe pas de placement idéal pour tout : chaque support a ses forces et ses contraintes.\nCette leçon compare la BRVM à l’épargne bancaire, à l’immobilier et au commerce, puis montre les rendements de dividende réels du marché.","avertissement":"Ceci n’est pas un conseil en investissement. Les performances passées ne préjugent pas des performances futures. Investir en actions comporte un risque de perte en capital.","sections":[{"type":"definition","titre":"Quatre placements, quatre profils","contenu":"Comparer les placements suppose de regarder quatre critères ensemble : le rendement espéré, le risque de perte en capital, la liquidité (vitesse de sortie) et l’horizon recommandé.\nEn UEMOA, le taux directeur de la BCEAO sert de boussole monétaire (3,00 % au 16 mars 2026, guichet marginal à 5,00 %).\nAucun placement ne gagne sur les quatre tableaux : un livret offre une liquidité totale mais un rendement modeste ; les actions offrent le potentiel long terme mais fluctuent fortement.","tableau":{"colonnes":["Placement","Rendement","Liquidité","Risque","Effort"],"lignes":[["Épargne bancaire","Faible, connu d’avance","Immédiate","Très faible","Aucun"],["Actions BRVM","Dividendes et variation du cours, non garantis","Rapide si la valeur s’échange","Moyen à élevé à court terme","Faible"],["Immobilier","Loyers et valeur du bien","Faible : des mois pour vendre","Moyen","Élevé : gestion, entretien"],["Commerce propre","Très variable","Très faible","Élevé","Très élevé"]],"note":"Repères qualitatifs : les rendements réels varient selon les périodes, les produits et les situations."}},{"type":"cas","reel":true,"titre":"Les rendements de dividende réels du marché","contenu":"Sur le compartiment obligataire de la BRVM au 24 novembre 2026, les emprunts d’État et privés cotés affichent des coupons faciaux de 6,15 % (ETAT DU SENEGAL 6,15% 2023-2030), 6,30 % (ETAT DU MALI 6,30% 2022-2032) ou 6,80 % (GSS BAOBAB 6,80% 2024-2029).\nFace à ces coupons fixes, les actions les plus généreuses versent des dividendes nets entre 5,78 % (SPHC) et 8,37 % (STBC) en 2026, auxquels s’ajoute la variation possible du cours.\nEntre les deux, les OPCVM (FCP) mutualisent un panier géré par un professionnel, moyennant des frais de gestion annuels.","donnees_reelles":{"vue":"rendement","codes":["SNTS","ORAC","SGBC","STBC","BOAB","CIEC"]},"graphiques":[{"type":"bar","titre":"Repères réels de rendement en UEMOA (%) : BCEAO, obligations et dividendes nets","reel":true,"note":"Sources : BCEAO (16/03/2026), BRVM Obligations (24/11/2026) et Calendrier officiel des dividendes BRVM (ex. 2025).","labels":["Taux BCEAO","Sénégal 2030","Mali 2032","Baobab 2029","SGBC (div. net)","ABJC (div. net)","STBC (div. net)"],"valeurs":[3,6.15,6.3,6.8,6.11,7.78,8.37]}]},{"type":"importance","titre":"Comparer sur la bonne durée","contenu":"Une seule année peut être exceptionnellement bonne ou mauvaise. Comparez sur cinq à dix ans, et toujours dividendes compris.\nLe rendement total additionne les dividendes et la variation du cours.","formules":[{"nom":"Rendement total sur un an","expression":"(Dividendes + Cours final − Cours initial) ÷ Cours initial × 100","exemple":"(400 + 10 600 − 10 000) ÷ 10 000 × 100 = 10 %"}],"simulation":{"type":"rendement_total","consigne":"Comparez avec et sans dividende, puis allongez la durée : le rendement annuel moyen se compare d’un placement à l’autre.","prix_achat":10000,"prix_vente":10600,"actions":1,"dividendes_par_action":400,"annees":1},"illustration":{"gabarit":"decomposition","titre":"Un an de bourse : dividende et hausse du cours (exemple de la leçon)","operation":"somme","resultat":{"label":"Rendement total sur un an","valeur":10,"pourcentage":true},"facteurs":[{"label":"Dividende (400 FCFA)","valeur":4,"pourcentage":true},{"label":"Hausse du cours (600 FCFA)","valeur":6,"pourcentage":true}],"note":"Pour une action achetée 10 000 FCFA, le même placement afficherait 6 % sans le dividende au lieu de 10 % : comparez toujours dividendes compris."}},{"type":"importance","titre":"Bâtir un patrimoine par étapes","contenu":"Comment articuler ces placements dans la vraie vie ? Par couches successives plutôt qu’en opposant un produit à un autre.\nCouche 1 (urgence, disponible sous 24 h) : épargne bancaire ou livret pour couvrir 3 à 6 mois de dépenses.\nCouche 2 (moyen terme, 2 à 5 ans) : dépôts à terme, obligations UEMOA ou OPCVM obligataires pour stabiliser le capital.\nCouche 3 (long terme, 5 ans et plus) : actions BRVM diversifiées et réinvestissement des dividendes.","etapes_style":"frise","etapes":[{"titre":"Épargne de précaution","detail":"Trois à six mois de charges, disponibles immédiatement.","cle":true},{"titre":"Placements de long terme","detail":"Actions BRVM diversifiées, pour l’argent dont on n’a pas besoin avant plusieurs années."},{"titre":"Actifs réels","detail":"Immobilier ou activité propre, selon ses moyens et son temps."}]},{"type":"importance","titre":"Ce que la bourse apporte, et ce qu’elle demande","contenu":"Face à l’immobilier ou au commerce, la bourse se distingue sur deux points : la liquidité et le peu de temps qu’elle exige.","points":[{"titre":"Liquidité","detail":"Une action qui s’échange se vend en séance, quand un bien immobilier peut demander des mois."},{"titre":"Peu de gestion","detail":"Ni locataire, ni stock, ni salarié : le suivi se limite aux publications et au portefeuille."},{"titre":"Fractionnement","detail":"On peut investir des montants modestes, et répartir sur plusieurs sociétés."},{"titre":"En contrepartie, la volatilité","detail":"Le cours varie chaque jour : la bourse convient à l’argent dont on n’a pas besoin à court terme.","verifier":"votre horizon de placement avant d’investir."}]},{"type":"piege","titre":"Les erreurs de comparaison","contenu":"Une comparaison mal posée conduit à de mauvaises décisions.","points":[{"titre":"Juger sur une seule année","detail":"« La bourse a baissé cette année » ne dit rien du rendement sur dix ans."},{"titre":"Oublier les dividendes","detail":"Ne regarder que le cours sous-estime le rendement des actions."},{"titre":"Comparer un brut à un net","detail":"Rendements de dividendes, loyers et intérêts se comparent après impôts et frais."},{"titre":"Tout mettre sur un seul support","detail":"Un patrimoine solide combine plusieurs placements."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Cinq idées à garder en tête.","points":[{"titre":"Aucun placement n’est idéal pour tout","detail":"Chacun a son rendement, sa liquidité, son risque et son effort."},{"titre":"La bourse offre liquidité et peu de gestion","detail":"En échange d’une volatilité à court terme."},{"titre":"Rendement total = dividendes + variation du cours","detail":"Le rendement de dividende n’en est qu’une partie."},{"titre":"On compare sur cinq à dix ans","detail":"Et toujours dans les mêmes conditions : brut avec brut, net avec net."},{"titre":"L’épargne de précaution vient en premier","detail":"Avant la bourse, avant l’immobilier."}]}],"quiz":[{"question":"Quel placement offre la liquidité la plus immédiate ?","options":["L’épargne bancaire","L’immobilier","Un commerce","Aucun des trois"],"correct":0,"explication":"L’épargne bancaire est disponible immédiatement, ce qui en fait le support naturel de l’épargne de précaution."},{"question":"Vous achetez une action 10 000 FCFA. Un an plus tard, elle cote 10 600 FCFA et vous avez reçu 400 FCFA de dividende. Quel est votre rendement total ?","options":["4 %","6 %","10 %","16 %"],"correct":2,"explication":"(400 + 10 600 − 10 000) ÷ 10 000 × 100 = 10 % : 4 % de dividende et 6 % de hausse du cours."},{"question":"Pourquoi comparer les placements sur cinq à dix ans ?","options":["Parce que les dividendes ne sont versés qu’au bout de cinq ans","Parce qu’une seule année peut être exceptionnelle","Parce que la BRVM ne publie ses cours qu’une fois par an","Parce que l’immobilier ne se vend qu’après dix ans"],"correct":1,"explication":"Sur une seule année, le hasard pèse lourd. Une longue période donne une image plus fidèle du rendement."},{"question":"Qu’est-ce que le rendement de dividende d’une action ?","options":["Le dividende divisé par le cours, hors variation du cours","La hausse du cours sur un an","Le bénéfice de la société divisé par son chiffre d’affaires","Le rendement total garanti par la société"],"correct":0,"explication":"Rendement de dividende = dividende ÷ cours × 100. Il ne tient pas compte de la variation du cours, qui s’ajoute au rendement total."},{"question":"Par quoi commencer pour bâtir un patrimoine ?","options":["Un portefeuille d’actions diversifié","Un bien immobilier en location","Une épargne de précaution","Un commerce de proximité"],"correct":2,"explication":"L’épargne de précaution couvre les imprévus : elle évite de devoir vendre ses actions ou son bien au mauvais moment."},{"question":"Quelle différence essentielle oppose une obligation d’État UEMOA (ex. 6,15 % à 6,30 %) à une action cotée ?","options":["L’obligation verse un coupon défini et rembourse le nominal à l’échéance (hors défaut)","L’obligation n’a jamais de date d’échéance","L’action garantit un remboursement fixe chaque année","L’obligation donne un droit de vote en AG d’entreprise"],"correct":0,"explication":"L’obligation est un titre de créance à échéancier défini ; l’action est un titre de propriété dont le dividende et le cours fluctuent."},{"question":"Quel est le rôle d’un OPCVM (ou FCP) par rapport à un achat d’actions en direct ?","options":["Supprimer tout risque de marché","Déléguer la gestion d’un portefeuille diversifié à un gérant agréé","Doubler le dividende net versé","Contourner les SGI agréées"],"correct":1,"explication":"Un OPCVM mutualise l’épargne et confie la sélection et le suivi à un gérant professionnel, en échange de frais de gestion."},{"question":"Pourquoi l’immobilier locatif ne remplace-t-il pas totalement les actifs financiers dans un patrimoine ?","options":["Parce que l’immobilier demande un ticket d’entrée élevé et reste peu liquide en cas de besoin rapide","Parce qu’il est interdit en UEMOA","Parce qu’il rapporte toujours 0 %","Parce qu’il est coté chaque jour à la BRVM"],"correct":0,"explication":"L’immobilier est peu fractionnable et long à vendre : la bourse apporte divisibilité et liquidité sur les grandes valeurs."},{"question":"Dans une allocation patrimoniale équilibrée, à quel horizon réserver les actions BRVM ?","options":["Moins de 3 mois","1 an maximum","5 ans et plus, une fois l’épargne de précaution constituée","Uniquement pour l’épargne de la semaine"],"correct":2,"explication":"Un horizon de 5 ans et plus permet d’absorber les baisses cycliques et de profiter du réinvestissement des dividendes."}],"qcm":{"question":"Quel placement offre la liquidité la plus immédiate ?","options":["L’épargne bancaire","L’immobilier","Un commerce","Aucun des trois"],"correct":0,"explication":"L’épargne bancaire est disponible immédiatement, ce qui en fait le support naturel de l’épargne de précaution."},"liens":[{"label":"Rendement réel et vrai","href":"/rendement-vrai"},{"label":"Espace dividendes","href":"/dividendes"}],"module":"Module 3 — Stratégies et compte","nouveaute":{"type":"mis_a_jour","depuis":"2026-11-24"},"charts":[]}$L10_M23_6$::jsonb
  );

